#!/usr/bin/env node
// Regenerates js/cue-font.js: the Inter 600 font as a data URL.
// Fullscreen subtitles are drawn by the page's own video, which cannot load the app's font files,
// so the font is injected into the page as a data URL (see pageTrackSync in js/subs.js).
//   node tools/build-cue-font.js
const fs = require('fs');
const path = require('path');

const root = path.join(__dirname, '..');
const data = fs.readFileSync(path.join(root, 'fonts', 'inter-600.woff2')).toString('base64');
const out = [
  '// Generated by tools/build-cue-font.js from fonts/inter-600.woff2 (Inter, SIL Open Font License). Do not edit.',
  "window.MF_CUE_FONT = 'data:font/woff2;base64," + data + "';",
  ''
].join('\n');
fs.writeFileSync(path.join(root, 'js', 'cue-font.js'), out);
console.log('js/cue-font.js written (' + out.length + ' bytes)');
